1	// Mailcow REST API client.
2	//
3	// Plain server-side module (NO "use server") — safe to import from server
4	// actions, route handlers, server components and the worker; never bundled to
5	// the client. Talks to a self-hosted Mailcow instance over its REST API.
6	//
7	// Configuration is read from the environment at call time (never hardcoded):
8	//   MAILCOW_API_URL  e.g. https://mail.nxeon.cloud/api/v1
9	//   MAILCOW_API_KEY  the X-API-Key value
10	//
11	// Every function throws a clear Error on a non-success response (including when
12	// Mailcow itself replies with a `{type:"danger"|"error"}` payload) or when the
13	// integration is not configured. Callers that must stay failure-tolerant (the
14	// order flow) wrap these in try/catch.
15	
16	/**
17	 * Sentinel `status` marking a TRANSPORT failure (Mailcow could not be reached at
18	 * all) as distinct from Mailcow answering and REFUSING. The difference decides
19	 * what a caller may safely do: an unreachable server may recover, so it is right
20	 * to let the customer keep a record and retry; a refusal ("mailbox still exists",
21	 * "permission denied") means the mail server and our database genuinely disagree,
22	 * and deleting our row while the real mailbox lives on is silent data loss.
23	 *
24	 * A negative number so it can never collide with a real HTTP status.
25	 */
26	export const MAILCOW_UNREACHABLE = -1;
27	
28	export class MailcowError extends Error {
29	  constructor(
30	    message: string,
31	    public status?: number,
32	    public body?: unknown,
33	  ) {
34	    super(message);
35	    this.name = "MailcowError";
36	  }
37	
38	  /** True when the server could not be reached at all (vs. reached and refused). */
39	  get unreachable(): boolean {
40	    return this.status === MAILCOW_UNREACHABLE;
41	  }
42	}
43	
44	/** Was this thrown because Mailcow was unreachable, rather than because it refused? */
45	export function isMailcowUnreachable(e: unknown): boolean {
46	  return e instanceof MailcowError && e.unreachable;
47	}
48	
49	/** Both env vars present and non-empty. */
50	export function mailcowConfigured(): boolean {
51	  return Boolean(
52	    process.env.MAILCOW_API_URL?.trim() && process.env.MAILCOW_API_KEY?.trim(),
53	  );
54	}
55	
56	function config(): { base: string; key: string } {
57	  const base = process.env.MAILCOW_API_URL?.trim();
58	  const key = process.env.MAILCOW_API_KEY?.trim();
59	  if (!base || !key) {
60	    throw new MailcowError(
61	      "Mailcow not configured — set MAILCOW_API_URL and MAILCOW_API_KEY.",
62	    );
63	  }
64	  return { base: base.replace(/\/+$/, ""), key };
65	}
66	
67	/**
68	 * Core request helper. Performs a fetch to `${MAILCOW_API_URL}${path}` with the
69	 * X-API-Key header, parses the JSON body, and throws a MailcowError on any
70	 * non-2xx status or on a Mailcow error payload.
71	 */
72	async function mcRequest(
73	  method: "GET" | "POST",
74	  path: string,
75	  body?: unknown,
76	): Promise<unknown> {
77	  const { base, key } = config();
78	  const url = `${base}${path.startsWith("/") ? path : `/${path}`}`;
79	
80	  let res: Response;
81	  try {
82	    res = await fetch(url, {
83	      method,
84	      headers: {
85	        "X-API-Key": key,
86	        "Content-Type": "application/json",
87	        Accept: "application/json",
88	      },
89	      body: body === undefined ? undefined : JSON.stringify(body),
90	      cache: "no-store",
91	    });
92	  } catch (e) {
93	    throw new MailcowError(
94	      `Mailcow unreachable (${method} ${path}): ${e instanceof Error ? e.message : String(e)}`,
95	      MAILCOW_UNREACHABLE,
96	    );
97	  }
98	
99	  const text = await res.text();
100	  let parsed: unknown = text;
101	  try {
102	    parsed = text ? JSON.parse(text) : null;
103	  } catch {
104	    // leave parsed as raw text
105	  }
106	
107	  if (!res.ok) {
108	    throw new MailcowError(
109	      `Mailcow ${method} ${path} -> HTTP ${res.status}`,
110	      res.status,
111	      parsed,
112	    );
113	  }
114	
115	  assertNoApiError(parsed, `${method} ${path}`);
116	  return parsed;
117	}
118	
119	/**
120	 * Mailcow POST endpoints return HTTP 200 even on logical failure, signalling the
121	 * outcome via `type` in the (array-wrapped) payload. Detect and surface those.
122	 */
123	function assertNoApiError(parsed: unknown, ctx: string): void {
124	  const entries = Array.isArray(parsed) ? parsed : [parsed];
125	  for (const entry of entries) {
126	    if (entry && typeof entry === "object" && "type" in entry) {
127	      const type = String((entry as { type: unknown }).type ?? "").toLowerCase();
128	      if (type === "danger" || type === "error") {
129	        const rawMsg = (entry as { msg?: unknown }).msg;
130	        const msg = Array.isArray(rawMsg) ? rawMsg.join(" ") : String(rawMsg ?? "unknown error");
131	        throw new MailcowError(`Mailcow ${ctx} failed: ${msg}`, undefined, parsed);
132	      }
133	    }
134	  }
135	}
136	
137	// ---------- Mutations ----------
138	
139	/** Create a mail domain (idempotent-ish: if it already exists Mailcow errors,
140	 * which callers may ignore). */
141	export async function mcCreateDomain(domain: string): Promise<unknown> {
142	  return mcRequest("POST", "/add/domain", {
143	    domain,
144	    description: `nxeon ${domain}`,
145	    aliases: 400,
146	    mailboxes: 100,
147	    defquota: 1024,
148	    maxquota: 102400,
149	    quota: 102400,
150	    active: "1",
151	    restart_sogo: "0",
152	  });
153	}
154	
155	/** True if the domain already exists in Mailcow. */
156	export async function mcDomainExists(domain: string): Promise<boolean> {
157	  try {
158	    const res = await mcRequest("GET", `/get/domain/${encodeURIComponent(domain)}`);
159	    // Mailcow returns {} (or []) for an unknown domain, or the domain object.
160	    if (!res) return false;
161	    if (Array.isArray(res)) return res.length > 0;
162	    if (typeof res === "object") {
163	      return "domain_name" in res || "domain" in res;
164	    }
165	    return false;
166	  } catch {
167	    return false;
168	  }
169	}
