171	export async function mcCreateMailbox(opts: {
172	  localPart: string;
173	  domain: string;
174	  name: string;
175	  password: string;
176	  quotaMB: number;
177	}): Promise<unknown> {
178	  return mcRequest("POST", "/add/mailbox", {
179	    local_part: opts.localPart,
180	    domain: opts.domain,
181	    name: opts.name,
182	    password: opts.password,
183	    password2: opts.password,
184	    quota: opts.quotaMB,
185	    active: "1",
186	  });
187	}
