197	/**
198	 * Set a new password on an existing mailbox (customer-initiated reset). Mailcow
199	 * requires both `password` and `password2`; `force_pw_update:"0"` means the user
200	 * is not forced to change it on next webmail login (we just gave them this one).
201	 */
202	export async function mcSetMailboxPassword(address: string, password: string): Promise<unknown> {
203	  return mcRequest("POST", "/edit/mailbox", {
204	    items: [address],
205	    attr: { password, password2: password, force_pw_update: "0" },
206	  });
207	}
208	
209	/** Change a mailbox quota (MB). */
210	export async function mcSetQuota(address: string, quotaMB: number): Promise<unknown> {
211	  return mcRequest("POST", "/edit/mailbox", {
212	    items: [address],
213	    attr: { quota: quotaMB },
214	  });
215	}
216	
217	/** Delete a mailbox. */
218	export async function mcDeleteMailbox(address: string): Promise<unknown> {
219	  return mcRequest("POST", "/delete/mailbox", [address]);
220	}
221	
222	// ---------- Mailbox discovery (read-only) ----------
223	
224	/** A mailbox as it actually exists on Mailcow, narrowed to what we can adopt. */
225	export type MailcowMailbox = {
226	  address: string; // Mailcow's `username` — the full email address
227	  domain: string;
228	  name: string;
229	  active: boolean;
230	  quotaBytes: number;
231	  quotaUsedBytes: number;
232	};
233	
234	/**
235	 * List the mailboxes that really exist on a domain (`GET /get/mailbox/all/<domain>`).
236	 *
237	 * WHY this exists: `resolveMailbox` used to read only `db.mailbox`, so a mailbox
238	 * that lives on Mailcow without a local row was completely invisible in the
239	 * portal — the "it's not detecting the mailbox I already have on this account"
240	 * report. This is the read half of the reconciliation; the adoption half
241	 * (lib/mail/imap.ts `discoverMailboxes`) gates on domain verification.
242	 *
243	 * A domain Mailcow doesn't know returns `{}`, which we normalise to `[]`.
244	 */
245	export async function mcListMailboxes(domain: string): Promise<MailcowMailbox[]> {
246	  const res = await mcRequest("GET", `/get/mailbox/all/${encodeURIComponent(domain)}`);
247	  const rows = Array.isArray(res) ? res : [];
248	  const want = domain.trim().toLowerCase();
249	  const out: MailcowMailbox[] = [];
250	  for (const r of rows) {
251	    if (!r || typeof r !== "object") continue;
252	    const o = r as Record<string, unknown>;
253	    const address = typeof o.username === "string" ? o.username.trim().toLowerCase() : "";
254	    if (!address.includes("@")) continue;
255	    const mboxDomain =
256	      typeof o.domain === "string" ? o.domain.trim().toLowerCase() : address.slice(address.lastIndexOf("@") + 1);
257	    // Never return a row for a different domain than the one asked for — the
258	    // caller uses the domain to decide ownership, so it must not be spoofable
259	    // by a surprising API response shape.
260	    if (mboxDomain !== want) continue;
261	    out.push({
262	      address,
263	      domain: mboxDomain,
264	      name: typeof o.name === "string" ? o.name : "",
265	      active: toActive(o.active),
266	      quotaBytes: Number(o.quota) > 0 ? Number(o.quota) : 0,
267	      quotaUsedBytes: Number(o.quota_used) > 0 ? Number(o.quota_used) : 0,
268	    });
269	  }
270	  return out;
271	}
272	
273	// ---------- Aliases ----------
274	
275	/** A mail alias as returned by Mailcow, narrowed to the fields the UI needs. */
276	export type MailcowAlias = {
277	  id: number;
278	  address: string; // the alias address (what mail is sent to)
279	  goto: string; // destination(s), comma-separated
280	  active: boolean;
281	  domain?: string;
282	};
283	
284	/** Coerce Mailcow's mixed number/string `active` flag to a boolean. */
285	function toActive(v: unknown): boolean {
286	  return v === 1 || v === "1" || v === true;
287	}
288	
289	/**
290	 * List all aliases configured on a domain (`GET /get/alias/all/<domain>`).
291	 * Mailcow returns an array of alias objects; a domain with no aliases yields an
292	 * empty array (or `{}`), which we normalise to `[]`.
293	 */
294	export async function mcListAliases(domain: string): Promise<MailcowAlias[]> {
295	  const res = await mcRequest("GET", `/get/alias/all/${encodeURIComponent(domain)}`);
296	  const rows = Array.isArray(res) ? res : [];
297	  const out: MailcowAlias[] = [];
298	  for (const r of rows) {
299	    if (!r || typeof r !== "object") continue;
300	    const o = r as Record<string, unknown>;
301	    const id = Number(o.id);
302	    const address = typeof o.address === "string" ? o.address : "";
303	    if (!Number.isFinite(id) || !address) continue;
304	    out.push({
305	      id,
306	      address,
307	      goto: typeof o.goto === "string" ? o.goto : "",
308	      active: toActive(o.active),
309	      domain: typeof o.domain === "string" ? o.domain : undefined,
310	    });
311	  }
312	  return out;
313	}
314	
315	/**
316	 * Create an alias (`POST /add/alias`). `goto` is the destination address (or a
317	 * comma-separated list) mail to `address` should be delivered to. Throws a
318	 * MailcowError on any logical failure (e.g. the alias already exists).
319	 */
320	export async function mcAddAlias(address: string, goto: string): Promise<unknown> {
321	  return mcRequest("POST", "/add/alias", {
322	    address,
323	    goto,
324	    active: "1",
325	  });
326	}
327	
328	/** Delete an alias by its Mailcow id (`POST /delete/alias` with `[id]`). */
329	export async function mcDeleteAlias(id: number): Promise<unknown> {
330	  return mcRequest("POST", "/delete/alias", [id]);
331	}
332	
333	// ---------- Sieve filters (auto-reply + forwarding) ----------
334	
335	/**
336	 * A per-mailbox sieve filter as stored in Mailcow's `sieve_filters` table.
337	 *
338	 * Mailcow chains scripts as: global_sieve_before -> user `prefilter` ->
339	 * the user's own personal script -> user `postfilter` -> global_sieve_after.
340	 * Only ONE filter per (username, filter_type) can be active at a time —
341	 * Mailcow deactivates the others whenever a filter is added/edited as active.
342	 * That is why lib/mail/sieve.ts compiles auto-reply AND forwarding into a
343	 * single managed script instead of one filter each.
344	 */
345	export type MailcowFilter = {
346	  id: number;
347	  username: string;
348	  scriptDesc: string;
349	  scriptData: string;
350	  filterType: string; // "prefilter" | "postfilter"
351	  active: boolean;
352	};
353	
354	export type MailcowFilterType = "prefilter" | "postfilter";
355	
356	function toFilterRows(res: unknown): MailcowFilter[] {
357	  const rows = Array.isArray(res) ? res : [];
358	  const out: MailcowFilter[] = [];
359	  for (const r of rows) {
360	    if (!r || typeof r !== "object") continue;
361	    const o = r as Record<string, unknown>;
362	    const id = Number(o.id);
363	    if (!Number.isFinite(id)) continue;
364	    out.push({
365	      id,
366	      username: typeof o.username === "string" ? o.username : "",
367	      scriptDesc: typeof o.script_desc === "string" ? o.script_desc : "",
368	      scriptData: typeof o.script_data === "string" ? o.script_data : "",
369	      filterType: typeof o.filter_type === "string" ? o.filter_type : "",
370	      active: toActive(o.active),
371	    });
372	  }
373	  return out;
374	}
375	
376	/**
377	 * List the sieve filters belonging to ONE mailbox
378	 * (`GET /get/filters/<address>`). Mailcow returns `{}` when there are none.
379	 *
380	 * Always pass a full address: `/get/filters/all` walks every domain on the
381	 * server, which would leak other tenants' scripts into our result.
382	 */
383	export async function mcListFilters(address: string): Promise<MailcowFilter[]> {
384	  const res = await mcRequest("GET", `/get/filters/${encodeURIComponent(address)}`);
385	  // Defence in depth: Mailcow scopes by username server-side, but we re-filter
386	  // so a wrong/greedy response can never hand one customer another's script.
387	  const want = address.trim().toLowerCase();
388	  return toFilterRows(res).filter((f) => f.username.trim().toLowerCase() === want);
389	}
390	
391	/** Create a sieve filter on a mailbox (`POST /add/filter`). */
392	export async function mcAddFilter(opts: {
393	  address: string;
394	  scriptDesc: string;
395	  scriptData: string;
396	  filterType: MailcowFilterType;
397	  active?: boolean;
398	}): Promise<unknown> {
399	  return mcRequest("POST", "/add/filter", {
400	    username: opts.address,
401	    script_desc: opts.scriptDesc,
402	    script_data: opts.scriptData,
403	    filter_type: opts.filterType,
404	    active: opts.active === false ? "0" : "1",
405	  });
406	}
407	
408	/**
409	 * Replace the body of an existing filter (`POST /edit/filter`).
410	 *
411	 * Mailcow keeps the current value for any field it receives EMPTY, so
412	 * `scriptData` must never be blank here — clearing a rule is a delete, not an
413	 * edit with an empty script.
414	 */
415	export async function mcEditFilter(
416	  id: number,
417	  attr: { scriptDesc: string; scriptData: string; filterType: MailcowFilterType; active?: boolean },
418	): Promise<unknown> {
419	  if (!attr.scriptData.trim()) {
420	    throw new MailcowError("Refusing to edit a sieve filter with an empty script — delete it instead.");
421	  }
422	  return mcRequest("POST", "/edit/filter", {
423	    items: [id],
424	    attr: {
425	      script_desc: attr.scriptDesc,
426	      script_data: attr.scriptData,
427	      filter_type: attr.filterType,
428	      active: attr.active === false ? "0" : "1",
429	    },
430	  });
431	}
432	
433	/** Delete a sieve filter by its Mailcow id (`POST /delete/filter`). */
434	export async function mcDeleteFilter(id: number): Promise<unknown> {
435	  return mcRequest("POST", "/delete/filter", [id]);
436	}
437	
438	// ---------- DKIM ----------
439	
440	/**
441	 * Fetch the DKIM public-key TXT value for a domain from Mailcow
442	 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
443	 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
444	 * or null when the domain has no DKIM key yet or the shape is unexpected.
445	 *
446	 * Throws MailcowError only when the integration is unreachable/errors — callers
447	 * that must stay tolerant wrap this in try/catch.
448	 */
449	export async function mcGetDkim(domain: string): Promise<string | null> {
450	  return (await mcGetDkimDetails(domain))?.txt ?? null;
451	}
452	
453	/** The signing key Mailcow will actually use, plus the selector it publishes under. */
454	export type MailcowDkim = { selector: string; txt: string; bits: number | null };
455	
456	/**
457	 * Fetch the LIVE DKIM key + selector for a domain.
458	 *
459	 * The deliverability self-check must compare published DNS against this, never
460	 * against `EmailSubscription.dkimRecord`: that column is a cache written once at
461	 * DNS-setup time, so if the key is ever rotated (or the domain re-created on
462	 * Mailcow, which regenerates it) the cache silently describes a key that no
463	 * longer signs anything — and the check would tell a customer their DNS is
464	 * correct while every message they send fails DKIM.
465	 */
466	export async function mcGetDkimDetails(domain: string): Promise<MailcowDkim | null> {
467	  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
468	  if (!res || typeof res !== "object") return null;
469	  // Mailcow returns {} for a domain with no key configured.
470	  const o = res as Record<string, unknown>;
471	  const txt = typeof o.dkim_txt === "string" ? o.dkim_txt.trim() : "";
472	  if (!txt) return null;
473	  const selector = typeof o.dkim_selector === "string" && o.dkim_selector.trim() ? o.dkim_selector.trim() : "dkim";
474	  const bits = Number(o.length);
475	  return { selector, txt, bits: Number.isFinite(bits) && bits > 0 ? bits : null };
476	}
477	
478	// ---------- Analytics ----------
479	
480	export type MailStats = {
481	  configured: true;
482	  domains: number;
483	  mailboxes: number;
484	  postfix: {
485	    sampled: number;
486	    sent: number;
487	    deferred: number;
488	    bounced: number;
489	    rejected: number;
490	    other: number;
491	  };
492	  rspamd: {
493	    sampled: number;
494	    actions: Record<string, number>;
495	    spam: number; // reject + add header + rewrite subject
496	    clean: number; // no action + greylist / soft reject
497	  };
498	};
499	
500	function asArray(v: unknown): unknown[] {
501	  if (Array.isArray(v)) return v;
502	  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
503	    return (v as { rows: unknown[] }).rows;
504	  }
505	  return [];
506	}
507	
508	/**
509	 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
510	 * deliverability view. Throws (MailcowError) if not configured or unreachable —
511	 * the admin page catches that and shows a graceful fallback.
512	 */
513	export async function mcStats(sample = 400): Promise<MailStats> {
514	  config(); // throws early with a clear message if not configured
515	
516	  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
517	    mcRequest("GET", "/get/domain/all").catch(() => []),
518	    mcRequest("GET", "/get/mailbox/all").catch(() => []),
519	    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
520	    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
521	  ]);
522	
523	  const postfixLogs = asArray(postfixRaw);
524	  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
525	  for (const entry of postfixLogs) {
526	    const msg = String(
527	      (entry as { message?: unknown })?.message ??
528	        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
529	        "",
530	    ).toLowerCase();
531	    if (msg.includes("status=sent")) postfix.sent++;
532	    else if (msg.includes("status=deferred")) postfix.deferred++;
533	    else if (msg.includes("status=bounced")) postfix.bounced++;
534	    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
535	    else postfix.other++;
536	  }
537	
538	  const rspamdLogs = asArray(rspamdRaw);
539	  const actions: Record<string, number> = {};
540	  let spam = 0;
541	  let clean = 0;
542	  for (const entry of rspamdLogs) {
543	    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
544	    actions[action] = (actions[action] ?? 0) + 1;
545	    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
546	    else clean++;
547	  }
548	
549	  return {
550	    configured: true,
551	    domains: asArray(domainsRaw).length,
552	    mailboxes: asArray(mailboxesRaw).length,
553	    postfix,
554	    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
555	  };
556	}
