69	/** The TLS servername the mail server's certificate is issued for. */
70	export const MAIL_TLS_SERVERNAME = process.env.MAIL_TLS_SERVERNAME || "mail.nxeon.cloud";
71	
72	/**
73	 * TLS options for every webmail connection to the mail server (IMAP 993 and
74	 * SMTP submission 587). Shared so the two cannot drift apart.
75	 *
76	 * WHY VERIFICATION IS ON. We connect by internal IP (10.20.0.10) while the
77	 * server presents a public certificate for `mail.nxeon.cloud`, so a bare
78	 * connection fails on the name mismatch. The previous code resolved that by
79	 * setting `rejectUnauthorized: false` — which does not just tolerate the name
80	 * mismatch, it accepts ANY certificate from anything answering on that address.
81	 * The very first thing sent over that session is the customer's mailbox password
82	 * (IMAP LOGIN / SMTP AUTH), so anyone able to answer on the NAT bridge could
83	 * have harvested every mailbox credential on the platform, and nothing would
84	 * have looked wrong. `servername` alone is the correct fix: it sets SNI *and*
85	 * the name validation is performed against, so the real certificate verifies.
86	 *
87	 * MEASURED, not assumed (2026-07-27, from the app host):
88	 *   openssl s_client -connect 10.20.0.10:993 -servername mail.nxeon.cloud \
89	 *     -verify_return_error   ->  CN=mail.nxeon.cloud, "Verification: OK"
90	 *   …and the same on :587 with -starttls smtp.
91	 *
92	 * `MAIL_TLS_INSECURE=1` is a documented break-glass for an operator whose
93	 * certificate has genuinely expired mid-incident: it restores the old behaviour
94	 * from `.env` without a code change. It defaults OFF, so the safe state is the
95	 * one you get by doing nothing — the opposite of what it replaces.
96	 */
97	export function mailTlsOptions(): { servername: string; rejectUnauthorized: boolean } {
98	  return {
99	    servername: MAIL_TLS_SERVERNAME,
100	    rejectUnauthorized: process.env.MAIL_TLS_INSECURE !== "1",
101	  };
102	}
