134	/**
135	 * Adopt mailboxes that exist on Mailcow but have no local `Mailbox` row.
136	 *
137	 * WHY: `resolveMailbox` read ONLY `db.mailbox`, so a mailbox created directly on
138	 * the mail server — or one whose row was lost — was invisible in the portal even
139	 * though real mail was landing in it ("its not detecting the mailbox that i
140	 * already have on this account"). This reconciles the two.
141	 *
142	 * OWNERSHIP GUARD — the whole point of this function is that it MUST NOT become
143	 * a way to acquire someone else's mailbox:
144	 *   1. Only domains on a non-cancelled subscription owned by THIS user are read.
145	 *   2. Only subscriptions with `verified === true` are eligible. Owning a
146	 *      subscription ROW is not proof of owning the DOMAIN — an unverified
147	 *      external subscription is just a claim, and adopting on a claim would
148	 *      re-open the cross-tenant takeover fixed on 2026-07-25 by a side door.
149	 *   3. `Mailbox.address` is globally `@unique`, and we skip any address that
150	 *      already has a row, so a mailbox another tenant legitimately holds is
151	 *      never re-pointed at this user.
152	 *   4. `passwordEnc` is left NULL. We never learn the existing password, so the
153	 *      customer is told to reset it — adoption grants visibility, not access.
154	 *
155	 * Never throws: a Mailcow outage must not turn the mail page into an error.
156	 * Returns the number of rows created.
157	 */
158	export async function discoverMailboxes(userId: string): Promise<number> {
159	  if (!mailcowConfigured()) return 0;
160	
161	  // Guard against hammering Mailcow: the mail page calls this on every load for
162	  // an account with no mailbox, which is exactly the account that reaches here.
163	  const gate = checkRateLimit(`mail:discover:${userId}`, { max: 1, windowMs: 30_000 });
164	  if (!gate.ok) return 0;
165	
166	  const subs = await db.emailSubscription.findMany({
167	    where: { userId, status: { not: "CANCELLED" }, verified: true },
168	    select: { id: true, domainName: true },
169	  });
170	  if (subs.length === 0) return 0;
171	
172	  let created = 0;
173	  for (const sub of subs) {
174	    const domain = sub.domainName.trim().toLowerCase();
175	    if (!domain) continue;
176	
177	    let remote: Awaited<ReturnType<typeof mcListMailboxes>>;
178	    try {
179	      remote = await mcListMailboxes(domain);
180	    } catch (e) {
181	      console.warn(`[mailcow] discovery for ${domain} failed:`, e);
182	      continue;
183	    }
184	    if (remote.length === 0) continue;
185	
186	    const existing = await db.mailbox.findMany({
187	      where: { address: { in: remote.map((m) => m.address) } },
188	      select: { address: true },
189	    });
190	    const known = new Set(existing.map((m) => m.address.toLowerCase()));
191	
192	    for (const m of remote) {
193	      if (known.has(m.address)) continue;
194	      try {
195	        await db.mailbox.create({
196	          data: {
197	            subscriptionId: sub.id,
198	            address: m.address,
199	            quotaMB: m.quotaBytes > 0 ? Math.round(m.quotaBytes / (1024 * 1024)) : null,
200	            status: m.active ? "ACTIVE" : "SUSPENDED",
201	            displayName: m.name && m.name !== m.address ? m.name : null,
202	          },
203	        });
204	        created++;
205	      } catch {
206	        // Unique-violation race (two tabs discovering at once) — the row exists
207	        // now either way, which is the outcome we wanted.
208	      }
209	    }
210	  }
211	
212	  if (created > 0) {
213	    await db.auditLog
214	      .create({ data: { userId, action: "mailbox.discover", detail: `adopted ${created} from mail server` } })
215	      .catch(() => {});
216	  }
217	  return created;
218	}
