232	/**
233	 * Diagnose mail access for a user. Runs Mailcow discovery first so a mailbox
234	 * that only exists on the server is found before we declare there is none.
235	 */
236	export async function mailAccessState(userId: string): Promise<MailAccessState> {
237	  await discoverMailboxes(userId).catch(() => 0);
238	
239	  const subs = await db.emailSubscription.findMany({
240	    where: { userId, status: { not: "CANCELLED" } },
241	    select: { domainName: true, verified: true, external: true },
242	  });
243	  if (subs.length === 0) return { kind: "no-subscription" };
244	
245	  const boxes = await db.mailbox.findMany({
246	    where: { subscription: { userId } },
247	    orderBy: { createdAt: "asc" },
248	    select: { address: true, passwordEnc: true },
249	  });
250	
251	  if (boxes.length === 0) {
252	    const unverified = subs.filter((s) => !s.verified).map((s) => s.domainName);
253	    const verified = subs.filter((s) => s.verified).map((s) => s.domainName);
254	    // An unverified domain is the more actionable problem: no mailbox can even
255	    // be created on it yet, so lead with that.
256	    if (verified.length === 0) return { kind: "unverified-domain", domains: unverified };
257	    return { kind: "no-mailbox", domains: verified };
258	  }
259	
260	  const withPassword = boxes.find((b) => decryptSecret(b.passwordEnc));
261	  if (!withPassword) return { kind: "no-password", address: boxes[0].address };
262	
263	  // A mailbox and a credential exist, so the page's failure was the mail server
264	  // itself (IMAP down, auth rejected, TLS problem) — not missing setup.
265	  return { kind: "server-unreachable", address: withPassword.address };
266	}
