268	/**
269	 * Resolve the mailbox a request may act on. Requires an authenticated user,
270	 * loads only mailboxes belonging to that user's email subscriptions, and (when
271	 * `mailboxAddress` is given) verifies it is one of them. Decrypts the stored
272	 * credential; throws a friendly error if the password was never captured.
273	 *
274	 * NEVER returns a mailbox the caller does not own.
275	 */
276	export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
277	  const user = await requireUser();
278	  const load = () =>
279	    db.mailbox.findMany({
280	      where: { subscription: { userId: user.id } },
281	      include: { subscription: true },
282	      orderBy: { createdAt: "asc" },
283	    });
284	
285	  let boxes = await load();
286	  const wanted = mailboxAddress?.trim().toLowerCase();
287	
288	  // A miss here used to be terminal, which is how a mailbox that exists on the
289	  // mail server but has no local row became "you do not have a mailbox yet".
290	  // Reconcile against Mailcow (verified domains only) before giving that answer.
291	  if (boxes.length === 0 || (wanted && !boxes.some((b) => b.address.toLowerCase() === wanted))) {
292	    if (await discoverMailboxes(user.id).catch(() => 0)) boxes = await load();
293	  }
294	
295	  if (boxes.length === 0) {
296	    throw new Error("You do not have a mailbox yet. Add an email plan to use webmail.");
297	  }
298	
299	  let box = boxes[0];
300	  if (wanted) {
301	    const match = boxes.find((b) => b.address.toLowerCase() === wanted);
302	    if (!match) throw new Error("You do not have access to that mailbox.");
303	    box = match;
304	  }
305	
306	  const password = decryptSecret(box.passwordEnc);
307	  if (!password) {
308	    throw new Error("Please reset your mailbox password first to enable webmail access.");
309	  }
310	
311	  return {
312	    user,
313	    mailboxId: box.id,
314	    address: box.address,
315	    quotaMB: box.quotaMB ?? null,
316	    cred: { address: box.address, password },
317	    identity: {
318	      displayName: box.displayName,
319	      replyTo: box.replyTo,
320	      organization: box.organization,
321	    },
322	    subscription: {
323	      id: box.subscription.id,
324	      domainName: box.subscription.domainName,
325	      external: box.subscription.external,
326	      verified: box.subscription.verified,
327	      status: box.subscription.status,
328	    },
329	  };
330	}
