332	/** Build a per-request imapflow client for the given credential. */
333	export function createImapClient(cred: MailboxCredentials): ImapFlow {
334	  return new ImapFlow({
335	    host: MAIL_IMAP_HOST,
336	    port: MAIL_IMAP_PORT,
337	    secure: true,
338	    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
339	    // and validation servername so TLS verifies against the right name.
340	    servername: MAIL_TLS_SERVERNAME,
341	    tls: mailTlsOptions(),
342	    auth: { user: cred.address, pass: cred.password },
343	    logger: false,
344	    disableAutoIdle: true,
345	  });
346	}
