348	/**
349	 * Open a short-lived IMAP connection, run `fn`, and ALWAYS close it (graceful
350	 * logout, falling back to a hard close). Suitable for one operation per request.
351	 */
352	export async function withImap<T>(cred: MailboxCredentials, fn: (client: ImapFlow) => Promise<T>): Promise<T> {
353	  const client = createImapClient(cred);
354	  await client.connect();
355	  try {
356	    return await fn(client);
357	  } finally {
358	    try {
359	      await client.logout();
360	    } catch {
361	      try {
362	        client.close();
363	      } catch {
364	        /* already gone */
365	      }
366	    }
367	  }
368	}
