370	/**
371	 * Like `withImap` but also selects `path` under a mailbox lock (released before
372	 * the connection closes). Use for any op that fetches/searches/mutates messages.
373	 */
374	export async function withMailbox<T>(
375	  cred: MailboxCredentials,
376	  path: string,
377	  fn: (client: ImapFlow) => Promise<T>,
378	  opts?: { readOnly?: boolean },
379	): Promise<T> {
380	  return withImap(cred, async (client) => {
381	    const lockOpts: MailboxLockOptions = { readOnly: opts?.readOnly };
382	    const lock = await client.getMailboxLock(path, lockOpts);
383	    try {
384	      return await fn(client);
385	    } finally {
386	      lock.release();
387	    }
388	  });
389	}
