391	/** Map an IMAP special-use flag / folder name to our MailFolderRole. */
392	export function folderRole(path: string, specialUse?: string): MailFolderRole {
393	  const su = (specialUse || "").toLowerCase();
394	  if (su === "\\inbox" || path.toUpperCase() === "INBOX") return "inbox";
395	  switch (su) {
396	    case "\\sent":
397	      return "sent";
398	    case "\\drafts":
399	      return "drafts";
400	    case "\\trash":
401	      return "trash";
402	    case "\\junk":
403	      return "junk";
404	    case "\\archive":
405	    case "\\all":
406	      return "archive";
407	  }
408	  // Fall back to common folder names for servers that don't advertise SPECIAL-USE.
409	  const leaf = (path.split(/[/.]/).pop() || path).toLowerCase();
410	  if (leaf === "inbox") return "inbox";
411	  if (["sent", "sent items", "sent mail", "sent messages"].includes(leaf)) return "sent";
412	  if (["drafts", "draft"].includes(leaf)) return "drafts";
413	  if (["trash", "deleted", "deleted items", "deleted messages", "bin"].includes(leaf)) return "trash";
414	  if (["junk", "spam", "junk email", "junk e-mail"].includes(leaf)) return "junk";
415	  if (["archive", "archives", "all mail", "all"].includes(leaf)) return "archive";
416	  return "custom";
417	}
