429	/**
430	 * Walk a BODYSTRUCTURE tree and return the IMAP part id of the best text part
431	 * to preview: prefers text/plain, then text/html, then the first leaf. Returns
432	 * "1" for a simple single-part message (whose structure carries no part id).
433	 */
434	export function findPreviewPart(structure: MessageStructureObject | undefined): { part: string; isHtml: boolean } {
435	  if (!structure) return { part: "1", isHtml: false };
436	  const leaves: MessageStructureObject[] = [];
437	  const walk = (node: MessageStructureObject) => {
438	    if (node.childNodes && node.childNodes.length) {
439	      node.childNodes.forEach(walk);
440	    } else {
441	      leaves.push(node);
442	    }
443	  };
444	  walk(structure);
445	
446	  const isBody = (n: MessageStructureObject) => (n.disposition || "").toLowerCase() !== "attachment";
447	  const plain = leaves.find((n) => (n.type || "").toLowerCase() === "text/plain" && isBody(n));
448	  if (plain) return { part: plain.part || "1", isHtml: false };
449	  const html = leaves.find((n) => (n.type || "").toLowerCase() === "text/html" && isBody(n));
450	  if (html) return { part: html.part || "1", isHtml: true };
451	  return { part: leaves[0]?.part || "1", isHtml: (leaves[0]?.type || "").toLowerCase() === "text/html" };
452	}
453	
454	/** True if a BODYSTRUCTURE tree contains at least one attachment-like part. */
455	export function structureHasAttachments(structure: MessageStructureObject | undefined): boolean {
456	  if (!structure) return false;
457	  let found = false;
458	  const walk = (node: MessageStructureObject) => {
459	    const type = (node.type || "").toLowerCase();
460	    const disp = (node.disposition || "").toLowerCase();
461	    if (node.childNodes && node.childNodes.length) {
462	      node.childNodes.forEach(walk);
463	      return;
464	    }
465	    if (disp === "attachment") found = true;
466	    else if (!type.startsWith("text/") && !type.startsWith("multipart/")) found = true;
467	  };
468	  walk(structure);
469	  return found;
470	}
