472	/** Read imapflow message flags into the summary booleans. */
473	export function readFlags(flags: Set<string> | undefined): { seen: boolean; flagged: boolean; answered: boolean } {
474	  const f = flags ?? new Set<string>();
475	  return { seen: f.has("\\Seen"), flagged: f.has("\\Flagged"), answered: f.has("\\Answered") };
