239	export async function orderEmailHosting(
240	  domainName: string,
241	  emailPlanId: string,
242	): Promise<Result> {
243	  const user = await requireUser();
244	  // Spend path: block while an admin is impersonating, so support cannot buy a
245	  // subscription with a customer's wallet while acting as them.
246	  //
247	  // This was the ONE purchase path in the product without this guard — every
248	  // other spend (order, resize, disk expand, volume, domain register/renew/
249	  // transfer, game plan upgrade, top-up) calls it. Impersonation is meant for
250	  // looking, never for spending: `realUser()` is the admin, `currentUser()` is
251	  // the customer, and a debit taken here would come out of the customer's
252	  // balance with the customer's name on the ledger row.
253	  await assertNotImpersonating();
254	  // Purchase gate: an unverified address means we cannot reach the person we
255	  // are about to charge. See lib/email-verification.ts.
256	  const unverified = await emailVerificationError(user);
257	  if (unverified) return { error: unverified };
258	
259	  const name = String(domainName ?? "")
260	    .trim()
261	    .toLowerCase()
262	    .replace(/\.$/, "");
263	  if (!name) return { error: "Enter a domain." };
264	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
265	
266	  // Is the domain registered inside Nxeon? If so we control its DNS and can
267	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
268	  // verified via DNS before mail flows.
269	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
270	  const external = !inAccount;
271	
272	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
273	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
274	
275	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
276	  //
277	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
278	  // which let anyone buy a subscription for a domain another customer already
279	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
280	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
281	  // ADDRESS — so an attacker could create admin@victim.com under their own
282	  // subscription, call resetMailboxPassword() (which passes its ownership check
283	  // because the row is theirs), and have the password of the victim's real, live
284	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
285	  const dupe = await db.emailSubscription.findFirst({
286	    where: { domainName: name, status: { not: "CANCELLED" } },
287	  });
288	  if (dupe) {
289	    return {
290	      error:
291	        dupe.userId === user.id
292	          ? "This domain already has an email subscription."
293	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
294	    };
295	  }
296	
297	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
298	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
299	  // strikethrough shown on the pricing page is the real renewal price and this
300	  // discounted value is the real first-term price — displayed === charged.
301	  const promo = currentPromo(new Date());
302	  const chargeCents = promoPriceCents(plan.priceCents, promo);
303	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
304	  if (user.balanceCents < chargeCents) {
305	    return { error: "Insufficient balance. Top up your wallet first." };
306	  }
307	
308	  try {
309	    await db.$transaction(async (tx) => {
310	      await debitWallet(tx, user.id, chargeCents);
311	      await tx.walletTransaction.create({
312	        data: {
313	          userId: user.id,
314	          amountCents: -chargeCents,
315	          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
316	        },
317	      });
318	      await tx.emailSubscription.create({
319	        data: {
320	          userId: user.id,
321	          domainName: name,
322	          emailPlanId: plan.id,
323	          status: "ACTIVE",
324	          autoRenew: true,
325	          expiresAt: addMonths(new Date(), plan.termMonths),
326	          // In-account domains: we control DNS, so treat as verified now. External
327	          // domains: not verified until the customer publishes DNS + we confirm it.
328	          external,
329	          verified: !external,
330	          verifiedAt: external ? null : new Date(),
331	          verifyToken: external ? randomBytes(24).toString("hex") : null,
332	        },
333	      });
334	    });
335	  } catch (e) {
336	    if (e instanceof InsufficientBalanceError) {
337	      return { error: "Insufficient balance. Top up your wallet first." };
338	    }
339	    throw e;
340	  }
341	
342	  await db.auditLog.create({
343	    data: {
344	      userId: user.id,
345	      action: "emailhosting.order",
346	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
347	    },
348	  });
349	  revalidatePath("/dashboard/email");
350	  return { ok: true };
351	}
