449	/**
450	 * Verify that an EXTERNAL domain's owner has published our verification record.
451	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
452	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
453	 * corroboration. The result is derived entirely server-side from live DNS —
454	 * client input never decides the outcome. Rate-limited per user + subscription.
455	 */
456	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
457	  const user = await requireUser();
458	
459	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
460	  if (!sub) return { error: "Subscription not found." };
461	  if (sub.userId !== user.id) return { error: "Not your subscription." };
462	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
463	  if (sub.verified) return { ok: true };
464	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
465	
466	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
467	    max: 6,
468	    windowMs: 60_000,
469	  });
470	  if (!rl.ok) {
471	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
472	  }
473	
474	  const domain = sub.domainName;
475	  const expected = `nxeon-verify=${sub.verifyToken}`;
476	
477	  // Primary signal: the verification TXT record must contain our exact token.
478	  let tokenFound = false;
479	  try {
480	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
481	    // Each record may be split into multiple strings — join per-record chunks.
482	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
483	  } catch {
484	    tokenFound = false;
485	  }
486	
487	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
488	  let mxOk = false;
489	  try {
490	    const mx = await resolveMx(domain);
491	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
492	  } catch {
493	    mxOk = false;
494	  }
495	
496	  if (!tokenFound) {
497	    return {
498	      error: mxOk
499	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
500	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
501	    };
502	  }
503	
504	  await db.emailSubscription.update({
505	    where: { id: sub.id },
506	    data: { verified: true, verifiedAt: new Date() },
507	  });
508	
509	  await db.auditLog.create({
510	    data: {
511	      userId: user.id,
512	      action: "emailhosting.verify",
513	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
514	    },
515	  });
516	  revalidatePath("/dashboard/email");
517	  return { ok: true };
518	}
