520	// ---------- Deliverability self-check ----------
521	
522	/**
523	 * Run the SPF / DKIM / DMARC / MX self-check for a subscription the caller owns.
524	 *
525	 * WHY: "my mail goes to spam" was previously undiagnosable from inside the
526	 * product — the platform owner hit exactly this and had to reach for an external
527	 * tool. This returns pass/fail per record with the value actually observed beside
528	 * the expected one, so the customer can see which DNS row is wrong.
529	 *
530	 * Two correctness rules this depends on:
531	 *   - DNS is read from the ZONE'S AUTHORITATIVE NAMESERVERS, never the system
532	 *     resolver (see lib/mail/deliverability.ts — this host's `hosts: files …`
533	 *     nsswitch order can answer from /etc/hosts and looks like a real lookup).
534	 *   - DKIM is compared against Mailcow's LIVE key, not `sub.dkimRecord`, which is
535	 *     a write-once cache that can outlive a key rotation.
536	 *
537	 * Rate-limited: each run makes several outbound DNS queries plus one Mailcow call.
538	 */
539	export async function checkEmailDeliverability(
540	  subscriptionId: string,
541	): Promise<{ error?: string; report?: DeliverabilityReport }> {
542	  const user = await requireUser();
543	
544	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
545	  if (!sub) return { error: "Subscription not found." };
546	  if (sub.userId !== user.id) return { error: "Not your subscription." };
547	  // A cancelled subscription's domain may since have been taken by another
548	  // customer (the duplicate guard in orderEmailHosting only excludes CANCELLED
549	  // rows), so the old owner must not keep a live probe pointed at it.
550	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
551	
552	  // NOTE on domain verification: this check deliberately does NOT require
553	  // `sub.verified`, unlike every action that changes mail routing. It only READS
554	  // public DNS and Mailcow's public DKIM key, changes nothing, and an unverified
555	  // domain is precisely the case a customer needs it for — gating it would hide
556	  // the diagnosis exactly when the records are wrong. Ownership of the
557	  // subscription is still required so the panel can't be used to scan arbitrary
558	  // domains through our server.
559	  const rl = checkRateLimit(`email-deliverability:${user.id}`, { max: 10, windowMs: 60_000 });
560	  if (!rl.ok) return { error: `Too many checks. Try again in ${rl.retryAfterSec}s.` };
561	
562	  // LIVE key only. A failure here degrades the DKIM row to "unknown" rather than
563	  // silently comparing against a cached value that may no longer sign anything.
564	  let dkim: { selector: string; txt: string } | null = null;
565	  if (mailcowConfigured()) {
566	    try {
567	      const live = await mcGetDkimDetails(sub.domainName);
568	      if (live) dkim = { selector: live.selector, txt: live.txt };
569	    } catch (e) {
570	      console.warn(`[mailcow] live dkim lookup for ${sub.domainName} failed:`, e);
571	    }
572	  }
573	
574	  try {
575	    const report = await checkDeliverability({
576	      domain: sub.domainName,
577	      mailHost: MAIL_HOST,
578	      spfInclude: SPF_INCLUDE,
579	      spfExpected: SPF_VALUE,
580	      dmarcExpected: DMARC_VALUE,
581	      dkim,
582	    });
583	    return { report };
584	  } catch (e) {
585	    console.warn(`[deliverability] check for ${sub.domainName} failed:`, e);
586	    return { error: "Couldn't complete the DNS check right now. Please try again in a moment." };
587	  }
588	}
