81	/**
82	 * Build the download URL for one attachment part of one message.
83	 *
84	 * `mailbox` is NOT optional decoration. `app/api/mail/attachment/route.ts` calls
85	 * `resolveMailbox(mailbox)`, and `resolveMailbox(undefined)` resolves the
86	 * account's DEFAULT (oldest) mailbox — not the one being read. The reading pane
87	 * used to build this href by hand and omit the parameter, so on an account with
88	 * two mailboxes every attachment opened from the second one was fetched with
89	 * `<uid>` interpreted against the FIRST mailbox's IMAP session. IMAP UIDs are
90	 * per-folder counters that start at 1 in every mailbox, so that lookup usually
91	 * SUCCEEDS and returns a different message's file — the wrong document, handed
92	 * over with no error anywhere. Centralised here so it cannot be forgotten again.
93	 */
94	export function mailAttachmentUrl(opts: {
95	  folder: string;
96	  uid: number;
97	  /** Either the bare IMAP part id or the `"<uid>:<partId>"` attachment id. */
98	  part: string;
99	  /** The mailbox the message was read from. */
100	  mailbox?: string;
101	}): string {
102	  const qs = new URLSearchParams({
103	    folder: opts.folder,
104	    uid: String(opts.uid),
105	    part: opts.part,
106	  });
107	  if (opts.mailbox) qs.set("mailbox", opts.mailbox);
108	  return `/api/mail/attachment?${qs.toString()}`;
109	}
