689	  await db.mailbox.update({ where: { id: mailbox.id }, data: { status: "PROVISIONING" } });
690	
691	  const status = await provisionMailboxOnMailcow({
692	    id: mailbox.id,
693	    address: mailbox.address,
694	    quotaMB: mailbox.quotaMB,
695	    subscription: { domainName: mailbox.subscription.domainName },
